<?php
// Isolated WordPress/WooCommerce lifecycle, concurrency and shared-query contract.
if (!defined('GPANTE_SUPPORT_LOCAL_TEST') || !GPANTE_SUPPORT_LOCAL_TEST || home_url() !== (defined('GPANTE_SUPPORT_TEST_URL') ? GPANTE_SUPPORT_TEST_URL : 'https://127.0.0.1:9443')) throw new RuntimeException('Isolated local test site required');
require_once __DIR__ . '/../wordpress-plugin/gpante-support-chat/includes/catalog.php';
gpante_support_search_index_register();
gpante_support_search_index_upgrade();
function index_check($value, $message) { if (!$value) throw new RuntimeException($message); echo "PASS $message\n"; }
function index_read($params) { $request=new WP_REST_Request('GET','/gpante-support/v1/search'); $request->set_query_params($params); return gpante_support_search_index_endpoint($request); }
$ids=[];
$page_link=static fn($url,$id)=>'https://gpante.com/index-fixture-'.$id.'/';
add_filter('page_link',$page_link,10,2);
$prior_main=$GLOBALS['wp_the_query'] ?? null;
$prior_query=$GLOBALS['wp_query'] ?? null;
$other_db=null;
$lock=null;
try {
    $topic='نمایهآزمایشی';
    for($i=0;$i<105;$i++) {
        $id=wp_insert_post(['post_title'=>"$topic سند $i",'post_type'=>'page','post_status'=>'publish','post_content'=>"متن عمومی $topic"],true);
        if(is_wp_error($id)) throw new RuntimeException('Index fixture insert failed');
        $ids[]=$id;
    }
    $bad=wp_insert_post(['post_title'=>'سند خراب نمایه','post_type'=>'page','post_status'=>'publish','post_content'=>'SECRET_STALE'],true); $ids[]=$bad;
    update_post_meta($bad,'_elementor_edit_mode','builder'); update_post_meta($bad,'_elementor_data','broken-json');
    $r=index_read(['search'=>$topic]);
    index_check(!is_wp_error($r) && count($r->get_data())===3 && $r->get_headers()['X-WP-Total']===105 && $r->get_headers()['X-GPante-Coverage']==='incomplete', 'one invalid neighbor preserves all healthy matches and reports incomplete coverage');
    $r=index_read(['search'=>'هیچعبارتموجودنیست']);
    index_check(!is_wp_error($r) && $r->get_data()===[] && $r->get_headers()['X-GPante-Invalid-Documents']===1, 'empty search retains explicit invalid-document coverage');
    update_post_meta($bad,'_elementor_edit_mode','');
    $r=index_read(['search'=>'SECRET_STALE']);
    index_check(!is_wp_error($r) && array_column($r->get_data(),'id')===[$bad] && $r->get_headers()['X-GPante-Coverage']==='complete', 'switching away from invalid builder selects the current ordinary editor and clears invalid status');
    $state=get_option('gpante_support_search_state'); $state['ready']=false; $state['cursor']=0; update_option('gpante_support_search_state',$state,false);
    $r=index_read(['search'=>$topic]);
    index_check($r->get_headers()['X-GPante-Index-Initializing']==='1' && $r->get_headers()['X-GPante-Coverage']==='incomplete', 'bootstrap readiness is explicit even when existing rows match');
    $lease=gpante_support_search_index_lease();
    gpante_support_search_index_batch();
    index_check(get_option('gpante_support_search_state')['cursor']===0, 'a second worker cannot advance a leased traversal');
    delete_option('gpante_support_search_lease');
    gpante_support_search_index_batch();
    $state=get_option('gpante_support_search_state');
    index_check($state['cursor']>0 && !$state['ready'] && $state['cursor']<=max($ids), 'one background batch advances a bounded cursor without declaring full coverage');
    for($i=0;$i<50 && gpante_support_search_index_health()['initializing'];$i++) gpante_support_search_index_batch();
    index_check(gpante_support_search_index_health()['complete'], 'resumable batches eventually reconcile every eligible ID');
    $meta_reads=[];
    $count_reads=static function($value,$id,$key) use (&$meta_reads) { if($key==='_elementor_data') $meta_reads[]=$id; return $value; };
    add_filter('get_post_metadata',$count_reads,10,3);
    $r=index_read(['search'=>$topic]);
    remove_filter('get_post_metadata',$count_reads,10);
    index_check(count(array_unique($meta_reads))<=3 && $r->get_headers()['X-WP-Total']===105, 'warm retrieval extracts only the returned three documents rather than rescanning 105 bodies');
    $first=$ids[0];
    wp_update_post(['ID'=>$first,'post_content'=>'متنایندکسجدید']);
    $r=index_read(['search'=>'متنایندکسجدید']);
    index_check(!is_wp_error($r) && array_column($r->get_data(),'id')===[$first], 'ordinary editor content changes update one document immediately');
    wp_update_post(['ID'=>$first,'post_password'=>'secret']);
    index_check(index_read(['search'=>'متنایندکسجدید'])->get_data()===[], 'password protection removes indexed content immediately');
    wp_update_post(['ID'=>$first,'post_password'=>'','post_content'=>"متن عمومی $topic"]);
    $r=index_read(['search'=>$topic]); $expected=array_column($r->get_data(),'id');
    $native=new WP_Query(); $GLOBALS['wp_the_query']=$native; $GLOBALS['wp_query']=$native;
    $native->query(['s'=>$topic,'posts_per_page'=>3,'post_type'=>['page','post','product']]);
    index_check($native->get('gpante_site_index') && array_column($native->posts,'ID')===$expected && (int)$native->found_posts===105, 'standard main WordPress search and AI use the same ranking and complete totals');
    $secondary=new WP_Query(['s'=>$topic,'posts_per_page'=>3,'post_type'=>'page']);
    index_check(!$secondary->get('gpante_site_index'), 'secondary and theme AJAX queries are not hijacked');
    $natural=wp_insert_post(['post_title'=>'آموزش کورل رایگان 2026 MDF','post_type'=>'page','post_status'=>'publish','post_content'=>'متن عمومی'],true); $ids[]=$natural;
    $question=new WP_Query(); $GLOBALS['wp_the_query']=$question; $GLOBALS['wp_query']=$question;
    $question->query(['s'=>'سلام لطفاً می خواهم شما به من آموزش کورل رایگان ۲۰۲۶ MDF معرفی کنید کجاست؟','posts_per_page'=>3]);
    index_check($question->get('gpante_site_index') && $question->get('gpante_index_intent')==='learning' && array_column($question->posts,'ID')===[$natural], 'full-question native fallback removes ordinary punctuation/request grammar while preserving topic, free, version and material');
    $nine='واژهیک واژهدو واژهسه واژهچهار واژهپنج واژهشش واژههفت واژههشت واژهنه';
    index_check(gpante_support_search_index_native_terms($nine)===$nine, 'nine explicit topic words remain conjunctive without the AI query eight-token cutoff');
    $oversized=new WP_Query(); $GLOBALS['wp_the_query']=$oversized; $GLOBALS['wp_query']=$oversized;
    $oversized->query(['s'=>implode(' ',array_map(static fn($i)=>'موضوع'.$i,range(1,17))),'posts_per_page'=>3]);
    ob_start(); gpante_support_search_index_notice(); $notice=ob_get_clean();
    index_check($oversized->get('gpante_site_index') && $oversized->get('gpante_index_invalid_query') && !$oversized->posts && str_contains($notice,'۱۶'), 'oversized native queries show an explicit limit instead of silently reverting to another search source');
    $misspelled=wp_insert_post(['post_title'=>'تراکتورنمونه رایگان 2026 MDF','post_type'=>'page','post_status'=>'publish','post_content'=>'داده عمومی'],true); $ids[]=$misspelled;
    $r=index_read(['search'=>'تراکتورنمونهه رایگان 2026 MDF']);
    index_check($r->get_data()===[] && rawurldecode($r->get_headers()['X-GPante-Suggestion'] ?? '')==='تراکتورنمونه رایگان 2026 mdf', 'an explicit bounded Unicode spelling suggestion preserves free, version and material terms without searching the correction');
    $GLOBALS['wpdb']->update($GLOBALS['wpdb']->posts,['post_status'=>'private'],['ID'=>$misspelled]); clean_post_cache($misspelled);
    index_check(gpante_support_search_index_suggestion('تراکتورنمونهه')===null && index_read(['search'=>'تراکتورنمونه'])->get_data()===[], 'current visibility also protects optional spelling suggestions when a lifecycle event was missed');
    $GLOBALS['wpdb']->update($GLOBALS['wpdb']->posts,['post_status'=>'publish'],['ID'=>$misspelled]); clean_post_cache($misspelled);
    index_check(gpante_support_search_index_suggestion('رایگن')===null && gpante_support_search_index_suggestion('2025')===null, 'free and numeric constraints are never suggested as alternative values');
    index_check(gpante_support_site_matches('آموزش كاربردي ۲۰۲۶',gpante_support_site_search_groups('اموزش کاربردی 2026')), 'general Persian/Arabic letters, alef typography and digits normalize consistently');
    foreach([['search'=>$topic,'url'=>'https://example.com'],['search'=>str_repeat('x',161)],['search'=>[], 'page'=>1],['search'=>$topic,'intent'=>'anything']] as $params) index_check(is_wp_error(index_read($params)), 'fallback rejects unsupported query fields and bounds');
    $key='gpante_si_'.md5(DB_NAME.':'.$GLOBALS['wpdb']->prefix.':'.$first);
    $other_db=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);
    $lock=$other_db->get_var($other_db->prepare('SELECT GET_LOCK(%s,0)',$key));
    index_check((string)$lock==='1','independent database connection acquires the document fixture lock');
    $state=get_option('gpante_support_search_state'); $state['cursor']=max($ids)+1000; $state['ready']=true; update_option('gpante_support_search_state',$state,false);
    wp_update_post(['ID'=>$first,'post_content'=>'پسازرقابتنمایه']);
    index_check(gpante_support_search_index_health()['initializing'], 'contended lifecycle write explicitly marks coverage incomplete');
    $state=get_option('gpante_support_search_state'); $state['ready']=true; update_option('gpante_support_search_state',$state,false);
    $negative_cache=wp_cache_get('notoptions','options'); wp_cache_set('notoptions',['gpante_support_search_dirty'=>true],'options');
    index_check(gpante_support_search_index_health()['initializing'], 'a fresh dirty marker overrides stale ready state and per-request negative option cache');
    wp_cache_set('notoptions',$negative_cache ?: [],'options');
    $other_db->get_var($other_db->prepare('SELECT RELEASE_LOCK(%s)',$key)); $lock=null;
    gpante_support_search_index_batch();
    index_check(gpante_support_search_index_health()['initializing'] && get_option('gpante_support_search_state')['cursor']<max($ids)+1000, 'a delayed ID below the old cursor restarts traversal and cannot prematurely declare completeness');
    for($i=0;$i<50 && gpante_support_search_index_health()['initializing'];$i++) gpante_support_search_index_batch();
    index_check(array_column(index_read(['search'=>'پسازرقابتنمایه'])->get_data(),'id')===[$first] && gpante_support_search_index_health()['complete'], 'reconciliation repairs a delayed concurrent write using current source content');
    $fail_once=true;
    $fail_replace=static function($sql) use (&$fail_once) { if($fail_once && str_starts_with(ltrim($sql),'REPLACE INTO') && str_contains($sql,gpante_support_search_index_table())) { $fail_once=false; return 'INVALID_FIXTURE_INDEX_REPLACE'; } return $sql; };
    add_filter('query',$fail_replace,10);
    $prior_suppression=$GLOBALS['wpdb']->suppress_errors(true);
    wp_update_post(['ID'=>$first,'post_content'=>'اصلاحخودکارپسازخطایپایگاه']);
    $GLOBALS['wpdb']->suppress_errors($prior_suppression); remove_filter('query',$fail_replace,10);
    index_check(!$fail_once && gpante_support_search_index_health()['initializing'], 'a transient index write failure durably marks incomplete coverage');
    for($i=0;$i<50 && gpante_support_search_index_health()['initializing'];$i++) gpante_support_search_index_batch();
    index_check(array_column(index_read(['search'=>'اصلاحخودکارپسازخطایپایگاه'])->get_data(),'id')===[$first] && gpante_support_search_index_health()['complete'], 'the background traversal automatically repairs a failed write without an explicit per-ID update');
    $change_once=true;
    $change_revision=static function($sql) use (&$change_once) { if($change_once && str_starts_with(ltrim($sql),'REPLACE INTO') && str_contains($sql,gpante_support_search_index_table())) { $change_once=false; update_option('gpante_support_search_dirty',wp_generate_uuid4(),false); $changed=get_option('gpante_support_search_state'); $changed['ready']=false; update_option('gpante_support_search_state',$changed,false); } return $sql; };
    add_filter('query',$change_revision,10); gpante_support_search_index_batch(); remove_filter('query',$change_revision,10);
    index_check(!$change_once && gpante_support_search_index_health()['initializing'] && get_option('gpante_support_search_state')['cursor']===0, 'a revision created after the batch snapshot survives its state commit and resets reconciliation');
    for($i=0;$i<50 && gpante_support_search_index_health()['initializing'];$i++) gpante_support_search_index_batch();
    index_check(gpante_support_search_index_health()['complete'] && !get_option('gpante_support_search_dirty',false), 'only a complete unchanged cycle clears the matching dirty revision');
    remove_action('save_post','gpante_support_search_index_changed',30);
    wp_update_post(['ID'=>$first,'post_content'=>'ویرایشهنگامخاموشی']);
    add_action('save_post','gpante_support_search_index_changed',30,1);
    gpante_support_search_index_activate();
    index_check(gpante_support_search_index_health()['initializing'], 'reactivation declares incomplete coverage until inactive-period edits reconcile');
    for($i=0;$i<50 && gpante_support_search_index_health()['initializing'];$i++) gpante_support_search_index_batch();
    index_check(array_column(index_read(['search'=>'ویرایشهنگامخاموشی'])->get_data(),'id')===[$first] && gpante_support_search_index_health()['complete'], 'reactivation reconciliation repairs edits missed while the plugin was inactive');
    delete_option('gpante_support_search_schema');
    $install_lease=gpante_support_search_index_lease();
    gpante_support_search_index_upgrade();
    index_check((int)get_option('gpante_support_search_schema',0)===0, 'a concurrent installer respects the schema lease');
    delete_option('gpante_support_search_lease');
    gpante_support_search_index_upgrade();
    for($i=0;$i<50 && gpante_support_search_index_health()['initializing'];$i++) gpante_support_search_index_batch();
    index_check(gpante_support_search_index_health()['complete'], 'schema initialization retries safely after a competing lease is released');
    echo "Native incremental search index integration passed.\n";
} finally {
    if($other_db && $lock) $other_db->get_var($other_db->prepare('SELECT RELEASE_LOCK(%s)',$key));
    if($other_db) $other_db->close();
    $GLOBALS['wp_the_query']=$prior_main; $GLOBALS['wp_query']=$prior_query;
    remove_filter('page_link',$page_link,10);
    foreach($ids as $id) { wp_delete_post($id,true); delete_transient('gpante_site_'.$id); }
    delete_option('gpante_support_search_lease');
    delete_option('gpante_support_search_dirty');
}
